//
// Where the diagram editor writes its generated SysML code.
// Kept as a small interface so the editor does not depend on DocumentModel/sysmllib directly
// (and can be tested with a fake target).
//

#ifndef STRUCTURASYSTEMS_SYSMLBLOCKTARGET_H
#define STRUCTURASYSTEMS_SYSMLBLOCKTARGET_H

#include <memory>
#include <optional>
#include <string>

class QObject;
class QString;

namespace StructuraSystems::Client {

    class SysMLBlockTarget {
    public:
        virtual ~SysMLBlockTarget() = default;

        /// Body of the block generated by the diagram editor, std::nullopt if the document has none.
        [[nodiscard]] virtual std::optional<std::string> readGeneratedBlock() = 0;

        /// Creates the block if necessary, otherwise replaces its body. Must not touch any other block.
        virtual void writeGeneratedBlock(const std::string &body) = 0;

        /// true if the block is written in KerML (instead of SysML v2).
        [[nodiscard]] virtual bool isKerML() { return false; }
    };

    /**
     * Creates the target for a document of the application (a DocumentModel).
     * Defined in DocumentBlockTarget.cpp; the view model tests link their own fake instead.
     * @param elementId row (element id) of the block to edit; empty = the document's generated block
     * @return nullptr if @p document is not a DocumentModel.
     */
    [[nodiscard]] std::unique_ptr<SysMLBlockTarget> createDocumentBlockTarget(QObject *document, const QString &elementId);
}

#endif //STRUCTURASYSTEMS_SYSMLBLOCKTARGET_H
